// Cadência aprovada:
//  boas-vindas (email)  — 2 dias depois de marcar, só se lead total >= 10 dias
//  meio (whatsapp)      — a meio do intervalo, só se lead total >= 14 dias
//  reta final (email)   — 7 dias antes da sessão, só se lead total >= 7 dias
//  lead < 7 dias        — sem nutrição (a confirmação 24h já cobre)
// Máx. 1 toque por sessão por dia (prioridade: reta final > meio > boas-vindas).
// Os flags nutricao* na Sessao evitam repetições entre dias.
const DIA = 24 * 60 * 60 * 1000;
const agora = Date.now();

// Sem envios ao domingo (regra de timing da marca)
const diaSemana = new Date().toLocaleDateString('en-US', { timeZone: 'Europe/Lisbon', weekday: 'short' });
if (diaSemana === 'Sun') return [];

const sessoes = ($json.data || []).filter(s => s.estado === 'agendada' || s.estado === 'confirmada');
const out = [];

for (const s of sessoes) {
  const criadoEm = new Date(s.criadoEm).getTime();
  const dataSessao = new Date(s.data).getTime();
  if (dataSessao <= agora) continue;

  const leadDias = (dataSessao - criadoEm) / DIA;
  const diasAte = Math.ceil((dataSessao - agora) / DIA);
  const diasDesde = Math.floor((agora - criadoEm) / DIA);
  const meioDoCaminho = criadoEm + (dataSessao - criadoEm) / 2;

  let toque = null;
  if (!s.nutricao7dEnviado && leadDias >= 7 && diasAte <= 7 && diasAte >= 2) {
    toque = { tipo: 'retafinal', canal: 'email', flagField: 'nutricao7dEnviado' };
  } else if (!s.nutricao14dEnviado && leadDias >= 14 && diasAte > 8 && agora >= meioDoCaminho) {
    toque = { tipo: 'meio', canal: 'whatsapp', flagField: 'nutricao14dEnviado' };
  } else if (!s.nutricaoBoasVindasEnviado && leadDias >= 10 && diasDesde >= 2 && diasAte > 8) {
    toque = { tipo: 'boasvindas', canal: 'email', flagField: 'nutricaoBoasVindasEnviado' };
  }
  if (!toque) continue;

  const telefone = (((s.cliente && s.cliente.telefone) || '')).replace(/\D/g, '');
  const telefoneCompleto = telefone.length === 9 ? '351' + telefone : telefone;
  const emailCliente = (s.cliente && s.cliente.email) || null;
  const temWhatsapp = ((s.cliente && s.cliente.temWhatsapp) !== false) && telefoneCompleto.length > 0;

  // Sem WhatsApp: o toque 'meio' cai para email; sem WhatsApp nem email, ignora o toque
  let canalFinal = toque.canal;
  if (canalFinal === 'whatsapp' && !temWhatsapp) {
    if (!emailCliente) continue;
    canalFinal = 'email';
  }
  if (canalFinal === 'email' && !emailCliente) continue;

  out.push({ json: {
    sessaoId: s.id,
    clienteId: s.clienteId,
    nome: (s.cliente && s.cliente.nome) || '',
    primeiroNome: (((s.cliente && s.cliente.nome) || '').split(' ')[0]) || '',
    telefone: telefoneCompleto,
    servico: s.servico || 'a tua sessão',
    dataSessaoISO: s.data,
    hora: s.hora || '',
    diasAteSessao: diasAte,
    tipoToque: toque.tipo,
    canal: canalFinal,
    flagField: toque.flagField,
  } });
}

return out;

const c = $('Classificar Toques').item.json;
const perfil = $json.data || $json;
const primeiraVez = (perfil.totalSessoes ?? 0) === 0;
const email = perfil.email || null;

const dataFmt = new Date(c.dataSessaoISO).toLocaleDateString('pt-PT', { timeZone: 'Europe/Lisbon', weekday: 'long', day: '2-digit', month: 'long' });

const REGRAS_COMUNS = [
  'REGRAS ABSOLUTAS',
  '- Português europeu sempre. Trata SEMPRE a cliente por tu: a tua sessão, quando chegares, o que precisas. É PROIBIDO usar sua/seu, si, consigo, Prezada, Cara, Estimada ou qualquer forma de cortesia formal',
  '- Começa com uma saudação simples: Olá [nome],',
  '- A cliente é mulher: usa sempre formas femininas (bem-vinda, preparada, descansada)',
  '- Nunca mencionar que esta mensagem foi gerada automaticamente, por um sistema ou por inteligência artificial',
  '- Nunca mencionar preços, promoções, descontos ou urgência artificial',
  '- Nunca usar linguagem comercial (aproveita, não percas, marca já, garante o teu lugar)',
  '- Nunca usar clichês de wellness/coach (a tua jornada, ouve o teu corpo, equilíbrio holístico)',
  '- Nunca usar superlativos vazios (incrível, fantástico, revolucionário, transformador)',
  '- Máximo 1 emoji subtil (ex.: um símbolo de folha), nunca mais',
  '- Nunca colar gerúndios no fim das frases (proporcionando, permitindo, promovendo, garantindo, contribuindo para)',
  '- Nunca usar a construção não é X é Y, nem mais do que X é Y',
  '- Nunca personificar o corpo (o teu corpo pede, o teu corpo agradece, ouve o que o corpo te diz)',
  '- Nunca citar fontes vagas (estudos demonstram, especialistas afirmam); afirma de forma simples ou omite',
  '- Nunca abrir com frases genéricas (No mundo de hoje, Cada vez mais, Nos dias que correm)',
  '- Nunca fechar com Em suma, Lembra-te, votos motivacionais ou frases que sirvam para qualquer texto',
  '- Evita travessões; usa vírgula, dois pontos ou ponto final',
  '- Evita listas de três (três adjetivos ou três exemplos seguidos); um ou dois chegam',
  '- Sem gerúndio contínuo à brasileira: estou a preparar, nunca estou preparando',
  '- Varia o comprimento das frases; frases curtas são bem-vindas',
  '- Sê concreta: quantidades, momentos do dia e gestos reais em vez de conselhos abstratos',
  '- Imperativo sempre na 2ª pessoa do singular (tu): reserva, tenta, experimenta, aproveita, respira, bebe. PROIBIDO o imperativo de "você": reserve, tente, experimente, aproveite, respire, beba',
].join('\n');

const FORMATO_EMAIL = 'FORMATO DE SAÍDA\nDevolve APENAS um objeto JSON válido, sem markdown e sem blocos de código, com exatamente esta estrutura:\n{"assunto": "...", "corpo": "..."}';
const FORMATO_WA = 'FORMATO DE SAÍDA\nDevolve APENAS um objeto JSON válido, sem markdown e sem blocos de código:\n{"corpo": "..."}';

const SYSTEMS = {
  boasvindas: 'És a voz da Essence Wellness, um centro de massagens de relaxamento íntimo em Vila Nova de Gaia. Escreves um email de boas-vindas para uma cliente que acabou de marcar uma sessão, mas a sessão só acontece daqui a várias semanas.\n\nO teu objetivo é fazer a cliente sentir-se bem-vinda e confirmada na decisão que tomou. Nunca vendes, nunca pressionas, nunca soas a lembrete administrativo.\n\n' + REGRAS_COMUNS + '\n- Assina sempre como Essence Wellness (nunca Flora nos emails)\n- Escolhe UM único ângulo: boas-vindas e validação da escolha; o que esperar ao chegar ao espaço; desconstruir o nervosismo de estreia (só se for primeira vez); a personalização da sessão; o ritual sensorial (aromas, silêncio, ambiente); reservar mentalmente este tempo; o que torna especial o serviço marcado\n- Se for a primeira vez da cliente, podes abordar a ansiedade de estreia com delicadeza; se não for, trata-a como alguém que já conhece o espaço\n- Corpo do email: 80-150 palavras, tom conversacional, sem listas nem bullet points\n- Um único convite suave no fim (ex.: deixar a porta aberta para dúvidas antes da sessão) - nunca clica aqui nem marca já\n\n' + FORMATO_EMAIL,
  meio: 'És Flora, a voz humana e próxima da Essence Wellness - um centro de massagens íntimo em Vila Nova de Gaia. Escreves uma mensagem de WhatsApp para uma cliente que já marcou sessão, a meio do intervalo de espera até à data marcada.\n\nEsta mensagem NÃO é sobre a marcação em si - é um toque de presença leve durante a espera. Não perguntes se vai confirmar, não menciones logística, não pareças um lembrete administrativo.\n\n' + REGRAS_COMUNS + '\n- Máximo 3 frases no corpo da mensagem (excluindo saudação e assinatura)\n- Assinatura obrigatória no fim: Flora ✦ | Essence Wellness\n- Escolhe UM ângulo: check-in casual sobre o ritmo atual; dica pequena de autocuidado para os dias que faltam (hidratação, alongar, respirar, dormir); curiosidade genuína com pergunta aberta; referência sazonal ligada a bem-estar; se primeira vez, desmistificar (não há nada que precise de preparar); se não, nota breve de antecipação genuína\n- Evita repetir o tema de validação de escolha (já usado no email de boas-vindas)\n- Termina sempre com uma pergunta aberta ou nota calorosa - nunca com um pedido de ação\n\n' + FORMATO_WA,
  retafinal: 'És a voz da Essence Wellness, um centro de massagens de relaxamento íntimo em Vila Nova de Gaia. Escreves o email de preparação enviado 7 dias antes da sessão marcada.\n\nO teu objetivo é ajudar a cliente a chegar preparada e tranquila, resolver dúvidas logísticas e gerar antecipação genuína - sem repetir os ângulos de validação de escolha nem de check-in casual já usados em contactos anteriores.\n\n' + REGRAS_COMUNS + '\n- Assina sempre como Essence Wellness\n- Inclui pelo menos UMA informação prática real: morada Av. da República nº 2208, Piso 2, Vila Nova de Gaia; chegar com alguns minutos de antecedência; roupa confortável; hidratação antes e depois; ou não encher a agenda logo a seguir à sessão\n- Escolhe UM ângulo: o que trazer/vestir e como preparar o corpo; como chegar; o que esperar passo a passo; as perguntas que a terapeuta vai fazer (zona de tensão, aroma); não encher a agenda a seguir; se primeira vez, reforço tranquilizador (não há maneira certa, só relaxar); se não, convite a pensar no que gostaria diferente desta vez\n- Corpo do email: 100-180 palavras, sem listas nem bullet points, tom de carta pessoal\n- Um único convite suave no fim - nunca clica aqui nem marca já\n\n' + FORMATO_EMAIL,
};

const userPrompt = [
  'Escreve a mensagem para esta cliente da Essence Wellness:',
  '',
  'Nome: ' + c.primeiroNome,
  'Serviço marcado: ' + c.servico,
  'Data da sessão: ' + dataFmt + (c.hora ? ' às ' + c.hora : ''),
  'Dias até à sessão: ' + c.diasAteSessao,
  'Primeira vez na Essence: ' + (primeiraVez ? 'sim' : 'não'),
  '',
  'Personaliza com o nome e o serviço sem forçar. Devolve apenas o JSON pedido.',
].join('\n');

// Sem email válido não há como enviar toques de email — saltar
if (c.canal === 'email' && !email) return [];

return [{ json: {
  systemPrompt: SYSTEMS[c.tipoToque],
  userPrompt,
  canal: c.canal,
  tipoToque: c.tipoToque,
  flagField: c.flagField,
  sessaoId: c.sessaoId,
  clienteId: c.clienteId,
  primeiroNome: c.primeiroNome,
  telefone: c.telefone,
  email,
} }];

const prep = $('Preparar Prompt Nutrição').item.json;
const raw = ($json.choices && $json.choices[0] && $json.choices[0].message && $json.choices[0].message.content) || '{}';

let d;
try {
  const clean = raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  d = JSON.parse(clean);
} catch (e) {
  throw new Error('Erro ao parsear JSON do Groq (' + prep.tipoToque + '): ' + e.message);
}

const corpo = (d.corpo || '').trim();
if (!corpo) throw new Error('Groq devolveu corpo vazio para ' + prep.tipoToque);

// Email: embrulhar o corpo no template da marca (mesmo estilo do email de onboarding)
let emailHtml = null;
if (prep.canal === 'email') {
  const paragrafos = corpo.split(/\n\n+/).map(p => '<p>' + p.replace(/\n/g, '<br>') + '</p>').join('');
  emailHtml = 'Template HTML da marca envolvendo: ' + paragrafos;
}

return [{ json: {
  canal: prep.canal,
  tipoToque: prep.tipoToque,
  flagField: prep.flagField,
  sessaoId: prep.sessaoId,
  telefone: prep.telefone,
  email: prep.email,
  assunto: d.assunto || 'Uma nota da Essence Wellness',
  corpo,
  emailHtml,
} }];
